import React, { useState, useRef, useEffect } from 'react';
import { useScroll } from '@react-three/drei';
import { semanticNavigator } from '../services/SemanticNavigator';

export const AIConcierge = () => {
    const [input, setInput] = useState('');
    const [isProcessing, setIsProcessing] = useState(false);
    const [message, setMessage] = useState("I am the Sentaient AI Concierge. Where would you like to go?");
    const scroll = useScroll();

    // Map targets to scroll positions based on TimelineManager SCROLL_TIMELINE
    const targetMap = {
        "hero": 0,
        "services": 0.42, // Interstellar / Services area
        "portfolio": 0.24, // Icebreaker / Portfolio area
        "about": 0.60, // Orbital Command / About area
        "pricing": 0.84, // Fantasy Quant area
        "contact": 0.94 // Contango / Contact area
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!input.trim() || isProcessing) return;

        setIsProcessing(true);
        setMessage("Analyzing your intent...");

        const result = await semanticNavigator.getDestination(input);
        
        if (result.target && targetMap[result.target] !== undefined) {
            setMessage(`Navigating to ${result.target}... (Confidence: ${(result.confidence * 100).toFixed(0)}%)`);
            
            // Scroll to the target offset
            const targetOffset = targetMap[result.target];
            if (scroll.el) {
                const maxScroll = scroll.el.scrollHeight - scroll.el.clientHeight;
                scroll.el.scrollTo({
                    top: targetOffset * maxScroll,
                    behavior: 'smooth'
                });
            }
        } else {
            setMessage("I couldn't quite understand that. Try asking for 'portfolio', 'services', or 'contact'.");
        }

        setIsProcessing(false);
        setInput('');
    };

    return (
        <div className="absolute bottom-10 left-10 w-96 p-6 bg-[#050505]/90 backdrop-blur-xl border border-green-500/30 rounded-2xl shadow-[0_0_30px_rgba(0,255,68,0.1)] pointer-events-auto">
            <div className="flex items-center gap-3 mb-4">
                <div className={`w-3 h-3 rounded-full ${isProcessing ? 'bg-yellow-400 animate-pulse' : 'bg-green-500'}`}></div>
                <h3 className="text-white font-mono tracking-widest text-sm font-bold uppercase">AI Concierge</h3>
            </div>
            
            <p className="text-gray-300 text-sm mb-4 font-light min-h-[40px]">
                {message}
            </p>

            <form onSubmit={handleSubmit} className="flex gap-2">
                <input 
                    type="text"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="e.g. 'Show me your work'"
                    className="flex-1 bg-black/50 border border-white/10 rounded-lg px-4 py-2 text-white text-sm focus:outline-none focus:border-green-500/50 transition-colors"
                    disabled={isProcessing}
                />
                <button 
                    type="submit"
                    disabled={isProcessing || !input.trim()}
                    className="bg-green-500 hover:bg-green-600 text-black px-4 py-2 rounded-lg font-bold text-sm transition-colors disabled:opacity-50"
                >
                    SEND
                </button>
            </form>
        </div>
    );
};
